-- Hungary: ES/DE/FR milestone translations for the 6 milestones in
-- migration 348. Hand-translated, not machine copy-paste.

-- hu-rtir-launch-2018
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-launch-2018', 'es', 'Se lanza el Reporte de Facturas en Tiempo Real (RTIR)', 'A partir del 1 de julio de 2018, la Administración Nacional de Hacienda y Aduanas de Hungría (NAV) exigió que las facturas B2B nacionales con un importe de IVA superior a 100.000 HUF se reportaran a través del sistema Online Szamla. Las facturas generadas por software debían reportarse de inmediato, sin intervención humana; las facturas en papel manuscritas tenían 5 días naturales (IVA de 100.000-500.000 HUF) o 1 día natural (IVA superior a 500.000 HUF). Se trata de una obligación de reporte de datos de la transacción, no de un mandato de facturación electrónica -- la factura en sí podía seguir siendo en papel o PDF, y nada exigía que se emitiera electrónicamente. Solo sus datos debían llegar a NAV, en tiempo real.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si ya reporta bajo RTIR, tenga en cuenta que el umbral original de 100.000 HUF y los plazos de gracia para facturas manuales descritos aquí ya han sido superados -- vea los siguientes hitos"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-launch-2018', 'de', 'Echtzeit-Rechnungsmeldung (RTIR) wird eingeführt', 'Ab dem 1. Juli 2018 verlangte die ungarische Nationale Steuer- und Zollverwaltung (NAV), dass inländische B2B-Rechnungen mit einem USt-Betrag über 100.000 HUF über das System Online Szamla gemeldet werden. Softwaregenerierte Rechnungen mussten sofort und ohne menschliches Eingreifen gemeldet werden; handschriftliche Papierrechnungen hatten 5 Kalendertage (USt 100.000-500.000 HUF) oder 1 Kalendertag (USt über 500.000 HUF) Zeit. Dies ist eine Pflicht zur Meldung von Transaktionsdaten, keine E-Rechnungspflicht -- die Rechnung selbst konnte weiterhin auf Papier oder als PDF vorliegen, nichts verlangte eine elektronische Ausstellung. Nur ihre Daten mussten in Echtzeit an die NAV gelangen.', '["Für diesen historischen Meilenstein ist noch keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Sie bereits unter RTIR melden, beachten Sie, dass die hier beschriebene ursprüngliche Schwelle von 100.000 HUF und die Karenzfristen für manuelle Rechnungen inzwischen überholt sind -- siehe die folgenden Meilensteine"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-launch-2018', 'fr', 'Lancement du reporting des factures en temps réel (RTIR)', 'À compter du 1er juillet 2018, l''Administration nationale hongroise des impôts et des douanes (NAV) a exigé que les factures B2B nationales dont le montant de TVA dépassait 100 000 HUF soient déclarées via le système Online Szamla. Les factures générées par logiciel devaient être déclarées immédiatement, sans intervention humaine ; les factures papier manuscrites disposaient de 5 jours calendaires (TVA de 100 000 à 500 000 HUF) ou 1 jour calendaire (TVA supérieure à 500 000 HUF). Il s''agit d''une obligation de déclaration des données de transaction, non d''une obligation de facturation électronique -- la facture elle-même pouvait rester au format papier ou PDF, rien n''imposant qu''elle soit émise électroniquement. Seules ses données devaient parvenir à la NAV, en temps réel.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si vous déclarez déjà via RTIR, notez que le seuil initial de 100 000 HUF et les délais de grâce pour les factures manuelles décrits ici ont depuis été dépassés -- voir les jalons suivants"]');

-- hu-rtir-threshold-2020
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-threshold-2020', 'es', 'Se elimina el umbral de IVA de RTIR -- toda factura B2B nacional debe reportarse', 'A partir del 1 de julio de 2020, el umbral de 100.000 HUF de IVA que había limitado el alcance de RTIR desde 2018 se eliminó por completo: toda factura B2B nacional entre sujetos pasivos en Hungría debe reportarse ahora a NAV a través de Online Szamla, independientemente de su valor. Sigue siendo una obligación de reporte de datos, no un mandato de facturación electrónica -- emitir la factura en sí de forma electrónica sigue siendo opcional.', '["Confirme que su software de facturación o contabilidad reporta toda factura B2B nacional a Online Szamla, no solo las que superaban el antiguo umbral de 100.000 HUF", "Revise cualquier flujo de facturación manual o de bajo valor que asumiera que las facturas pequeñas quedaban fuera de RTIR -- esa excepción ya no existe"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-threshold-2020', 'de', 'Die USt-Schwelle von RTIR entfällt -- jede inländische B2B-Rechnung muss gemeldet werden', 'Ab dem 1. Juli 2020 wurde die USt-Schwelle von 100.000 HUF, die den Anwendungsbereich von RTIR seit 2018 begrenzt hatte, vollständig abgeschafft: Jede inländische B2B-Rechnung zwischen steuerpflichtigen Personen in Ungarn muss nun unabhängig von ihrem Wert über Online Szamla an die NAV gemeldet werden. Weiterhin eine Datenmeldepflicht statt einer E-Rechnungspflicht -- die elektronische Ausstellung der Rechnung selbst bleibt optional.', '["Prüfen Sie, ob Ihre Rechnungs- oder Buchhaltungssoftware jede inländische B2B-Rechnung an Online Szamla meldet, nicht nur solche über der alten Schwelle von 100.000 HUF", "Überprüfen Sie manuelle oder Kleinbetrags-Rechnungsabläufe, die davon ausgingen, dass kleine Rechnungen außerhalb von RTIR liegen -- diese Ausnahme existiert nicht mehr"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-threshold-2020', 'fr', 'Le seuil de TVA de RTIR est supprimé -- toute facture B2B nationale doit être déclarée', 'À compter du 1er juillet 2020, le seuil de 100 000 HUF de TVA qui avait limité le champ d''application de RTIR depuis 2018 a été entièrement supprimé : toute facture B2B nationale entre assujettis en Hongrie doit désormais être déclarée à la NAV via Online Szamla, quelle que soit sa valeur. Il s''agit toujours d''une obligation de déclaration de données plutôt que d''une obligation de facturation électronique -- l''émission électronique de la facture elle-même reste facultative.', '["Vérifiez que votre logiciel de facturation ou de comptabilité déclare bien toute facture B2B nationale à Online Szamla, et pas seulement celles dépassant l''ancien seuil de 100 000 HUF", "Réexaminez tout flux de facturation manuel ou de faible valeur qui supposait que les petites factures échappaient à RTIR -- cette exemption n''existe plus"]');

-- hu-rtir-scope-2021
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-scope-2021', 'es', 'RTIR se extiende a B2C, exportaciones y entregas intracomunitarias', 'A partir del 1 de enero de 2021, Hungría amplió nuevamente el alcance de RTIR para cubrir facturas B2C, entregas intracomunitarias y facturas de exportación -- no solo B2B nacional. Llegados a este punto, la obligación de reporte de datos en tiempo real de RTIR se aplica prácticamente a toda factura relevante a efectos de IVA que emita una empresa húngara, sin importar quién sea el cliente o dónde se encuentre. Sigue siendo una obligación de reporte, no un requisito de emitir facturas electrónicas.', '["Amplíe su cobertura de reporte RTIR a facturas B2C, de exportación e intracomunitarias si antes se limitaba solo al B2B nacional", "Confirme que su sistema de facturación capta y reporta el tipo de transacción correcto para cada una de estas nuevas categorías incluidas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-scope-2021', 'de', 'RTIR wird auf B2C, Exporte und innergemeinschaftliche Lieferungen ausgeweitet', 'Ab dem 1. Januar 2021 erweiterte Ungarn den Anwendungsbereich von RTIR erneut auf B2C-Rechnungen, innergemeinschaftliche Lieferungen und Exportrechnungen -- nicht mehr nur auf inländisches B2B. Damit gilt die Echtzeit-Transaktionsdatenmeldepflicht von RTIR im Wesentlichen für jede umsatzsteuerlich relevante Rechnung, die ein ungarisches Unternehmen ausstellt, unabhängig davon, wer der Kunde ist oder wo er sich befindet. Dies bleibt eine Meldepflicht, keine Pflicht zur Ausstellung von E-Rechnungen.', '["Erweitern Sie Ihre RTIR-Meldeabdeckung auf B2C-, Export- und innergemeinschaftliche Rechnungen, falls sie zuvor nur auf inländisches B2B beschränkt war", "Prüfen Sie, ob Ihr Rechnungssystem den korrekten Transaktionstyp für jede dieser neu erfassten Kategorien erfasst und meldet"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-rtir-scope-2021', 'fr', 'RTIR s''étend au B2C, aux exportations et aux livraisons intracommunautaires', 'À compter du 1er janvier 2021, la Hongrie a de nouveau élargi le champ d''application de RTIR pour couvrir les factures B2C, les livraisons intracommunautaires et les factures d''exportation -- pas seulement le B2B national. À ce stade, l''obligation de déclaration des données de transaction en temps réel de RTIR s''applique pratiquement à toute facture pertinente au regard de la TVA qu''une entreprise hongroise émet, quel que soit le client ou sa localisation. Cela reste une obligation de déclaration, non une obligation d''émettre des factures électroniques.', '["Étendez votre couverture de déclaration RTIR aux factures B2C, d''exportation et intracommunautaires si elle était auparavant limitée au B2B national", "Vérifiez que votre système de facturation capture et déclare le type de transaction correct pour chacune de ces nouvelles catégories concernées"]');

-- hu-energy-b2b-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-energy-b2b-2025', 'es', 'Los proveedores de electricidad, gas y agua deben emitir facturas electrónicas a clientes B2B', 'A partir del 1 de julio de 2025, las facturas por el suministro de electricidad, gas natural y agua a clientes no particulares (empresas) deben emitirse exclusivamente en formato electrónico. Se trata de una obligación genuinamente distinta de la obligación de reporte de datos de RTIR anterior: es el primer requisito real de Hungría de que una factura se emita realmente de forma electrónica, no solo que se reporte. La legislación no prescribe un formato o canal de transmisión específico -- cualquier formato y método aceptado por NAV es válido. El alcance es limitado -- solo suministros B2B de energía y agua -- no un mandato de facturación electrónica para toda la economía.', '["Si suministra electricidad, gas natural o agua a clientes empresariales en Hungría, confirme que su proceso de facturación emite facturas electrónicas, no en papel, para esos suministros", "Como no se exige un formato específico, confirme con su contraparte o con NAV qué formato y canal electrónico aceptarán realmente antes de basarse únicamente en esto"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-energy-b2b-2025', 'de', 'Strom-, Gas- und Wasserversorger müssen B2B-Kunden E-Rechnungen ausstellen', 'Ab dem 1. Juli 2025 müssen Rechnungen für die Lieferung von Strom, Erdgas und Wasser an nicht-private (geschäftliche) Kunden ausschließlich in elektronischer Form ausgestellt werden. Dies ist eine grundlegend andere Pflicht als die oben beschriebene Datenmeldepflicht von RTIR: Es ist Ungarns erste echte Vorgabe, dass eine Rechnung tatsächlich elektronisch ausgestellt werden muss, nicht nur gemeldet wird. Das Gesetz schreibt kein bestimmtes Format oder Übermittlungsweg vor -- jedes von der NAV akzeptierte Format und jede akzeptierte Methode ist zulässig. Der Anwendungsbereich ist eng -- nur B2B-Lieferungen von Energie und Wasser -- keine gesamtwirtschaftliche B2B-E-Rechnungspflicht.', '["Wenn Sie Strom, Erdgas oder Wasser an Geschäftskunden in Ungarn liefern, stellen Sie sicher, dass Ihr Rechnungsprozess für diese Lieferungen elektronische statt Papierrechnungen ausstellt", "Da kein bestimmtes Format vorgeschrieben ist, klären Sie mit Ihrem Vertragspartner oder der NAV, welches elektronische Format und welchen Kanal diese tatsächlich akzeptieren, bevor Sie sich allein hierauf verlassen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-energy-b2b-2025', 'fr', 'Les fournisseurs d''électricité, de gaz et d''eau doivent émettre des factures électroniques aux clients B2B', 'À compter du 1er juillet 2025, les factures relatives à la fourniture d''électricité, de gaz naturel et d''eau à des clients non particuliers (professionnels) doivent être émises exclusivement sous forme électronique. Il s''agit d''une obligation véritablement différente de l''obligation de déclaration de données de RTIR décrite ci-dessus : c''est la première véritable exigence hongroise selon laquelle une facture doit réellement être émise électroniquement, et non simplement déclarée. La législation ne prescrit aucun format ni canal de transmission spécifique -- tout format et toute méthode acceptés par la NAV sont valables. Le champ d''application est étroit -- uniquement les fournitures B2B d''énergie et d''eau -- et non une obligation de facturation électronique à l''échelle de l''économie.', '["Si vous fournissez de l''électricité, du gaz naturel ou de l''eau à des clients professionnels en Hongrie, vérifiez que votre processus de facturation émet des factures électroniques, et non papier, pour ces fournitures", "Aucun format spécifique n''étant imposé, vérifiez auprès de votre contrepartie ou de la NAV quel format et quel canal électroniques seront effectivement acceptés avant de vous y fier uniquement"]');

-- hu-b2c-receipt-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-b2c-receipt-2026', 'es', 'El reporte de datos de recibos a NAV pasa a ser obligatorio', 'A partir del 1 de septiembre de 2026, las empresas húngaras también deberán suministrar datos de recibos -- no solo datos de facturas -- a los sistemas de NAV. Las empresas que utilicen cajas registradoras conectadas o cajas registradoras electrónicas cumplirán automáticamente; el resto deberá transmitir los datos del recibo en un plazo de 3 días. Se exige una transición completa a cajas registradoras electrónicas antes del 1 de julio de 2028. Al igual que el propio RTIR, se trata de una obligación de reporte de datos que cubre el lado del recibo/punto de venta de una transacción, no un requisito de emitir recibos o facturas en ningún formato electrónico concreto.', '["Si emite recibos en papel sin una caja registradora conectada, prepárese para transmitir los datos del recibo en un plazo de 3 días o adoptar una caja registradora conectada/electrónica antes de esta fecha", "Presupueste la transición completa a cajas registradoras electrónicas exigida antes del 1 de julio de 2028, aunque su proceso actual solo necesite por ahora la vía de reporte manual de 3 días"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-b2c-receipt-2026', 'de', 'Die Meldung von Belegdaten an die NAV wird verpflichtend', 'Ab dem 1. September 2026 müssen ungarische Unternehmen zusätzlich Belegdaten -- nicht nur Rechnungsdaten -- an die Systeme der NAV übermitteln. Unternehmen mit angeschlossenen Registrierkassen oder E-Kassen erfüllen dies automatisch; andere müssen die Belegdaten innerhalb von 3 Tagen übermitteln. Bis zum 1. Juli 2028 ist ein vollständiger Übergang zu E-Kassen erforderlich. Wie RTIR selbst ist dies eine Datenmeldepflicht, die die Beleg-/Kassenseite einer Transaktion betrifft, keine Pflicht, Belege oder Rechnungen in einem bestimmten elektronischen Format auszustellen.', '["Wenn Sie Papierbelege ohne angeschlossene Registrierkasse ausstellen, planen Sie entweder die Übermittlung der Belegdaten innerhalb von 3 Tagen oder die Einführung einer angeschlossenen Kasse/E-Kasse vor diesem Datum ein", "Kalkulieren Sie den bis zum 1. Juli 2028 erforderlichen vollständigen Übergang zu E-Kassen ein, auch wenn Ihr aktueller Prozess vorerst nur den manuellen 3-Tage-Meldeweg benötigt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-b2c-receipt-2026', 'fr', 'La déclaration des données de reçus à la NAV devient obligatoire', 'À compter du 1er septembre 2026, les entreprises hongroises devront également fournir des données de reçus -- pas seulement des données de factures -- aux systèmes de la NAV. Les entreprises utilisant des caisses enregistreuses connectées ou des caisses électroniques se conforment automatiquement ; les autres doivent transmettre les données du reçu dans un délai de 3 jours. Une transition complète vers les caisses électroniques est requise d''ici le 1er juillet 2028. Comme RTIR lui-même, il s''agit d''une obligation de déclaration de données couvrant le volet reçu/point de vente d''une transaction, non d''une obligation d''émettre des reçus ou des factures dans un format électronique particulier.', '["Si vous émettez des reçus papier sans caisse enregistreuse connectée, prévoyez soit de transmettre les données du reçu dans un délai de 3 jours, soit d''adopter une caisse connectée/électronique avant cette date", "Prévoyez la transition complète vers les caisses électroniques exigée d''ici le 1er juillet 2028, même si votre processus actuel n''a besoin pour l''instant que de la déclaration manuelle sous 3 jours"]');

-- hu-vida-2030
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-vida-2030', 'es', 'Entra en vigor el reporte digital transfronterizo B2B de ViDA', 'Con independencia de que Hungría promulgue algún día un mandato general de facturación electrónica B2B a nivel nacional -- a fecha de esta redacción, solo existen normas específicas por sector (energía/agua) y obligaciones de reporte de datos (RTIR, recibos), aunque hay un marco integral en fase de consulta --, la directiva del IVA en la Era Digital (ViDA) de la UE exige capacidad de facturación electrónica estructurada y reporte digital para las operaciones B2B intracomunitarias a partir del 1 de julio de 2030, derecho de la UE confirmado (Directiva (UE) 2025/516 del Consejo).', '["Las empresas que comercian transfronterizamente dentro de la UE deben prepararse para la capacidad de facturación electrónica conforme con EN 16931 y de reporte en esta fecha, con independencia del calendario nacional propio de Hungría", "Siga de cerca la consulta húngara sobre un marco integral de facturación electrónica (abierta en noviembre de 2025) por si su despliegue nacional llegara antes de este suelo a nivel de la UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-vida-2030', 'de', 'ViDAs grenzüberschreitende B2B-Digitalmeldung tritt in Kraft', 'Unabhängig davon, ob Ungarn jemals eine allgemeine inländische B2B-E-Rechnungspflicht erlässt -- zum Zeitpunkt dieser Erstellung existieren nur sektorspezifische Regelungen (Energie/Wasser) und Datenmeldepflichten (RTIR, Belege), auch wenn ein umfassendes Rahmenwerk in Konsultation ist --, verlangt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für innergemeinschaftliche B2B-Umsätze -- bestätigtes EU-Recht (Richtlinie (EU) 2025/516 des Rates).', '["Unternehmen, die grenzüberschreitend innerhalb der EU Handel betreiben, sollten bis zu diesem Datum EN-16931-konforme E-Rechnungs- und Meldefähigkeit einplanen, unabhängig vom eigenen innerstaatlichen Zeitplan Ungarns", "Verfolgen Sie Ungarns eigene Konsultation zu einem umfassenden E-Rechnungs-Rahmenwerk (eröffnet im November 2025) auf Anzeichen, dass die inländische Einführung noch vor dieser EU-weiten Untergrenze erfolgen könnte"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('hu-vida-2030', 'fr', 'L''obligation transfrontalière de déclaration numérique B2B de ViDA entre en vigueur', 'Indépendamment du fait que la Hongrie adopte un jour une obligation générale nationale de facturation électronique B2B -- au moment de la rédaction, seules des règles sectorielles (énergie/eau) et des obligations de déclaration de données (RTIR, reçus) existent, même si un cadre global est en cours de consultation --, la directive européenne TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B intracommunautaires à partir du 1er juillet 2030 -- droit de l''UE confirmé (directive (UE) 2025/516 du Conseil).', '["Les entreprises commerçant à l''échelle transfrontalière au sein de l''UE devraient prévoir une capacité de facturation électronique conforme à l''EN 16931 et de déclaration à cette date, indépendamment du calendrier national propre à la Hongrie", "Surveillez la consultation hongroise sur un cadre global de facturation électronique (ouverte en novembre 2025) : son déploiement national pourrait devancer ce plancher européen"]');
